786	     finding). Forcing the inline style directly, not only toggling the class
787	     that drives the CSS transition, removes any dependency on that transition
788	     ever visibly completing — belt and braces for exactly this failure mode. */
789	  function revealNow(el){
790	    el.classList.add('sc-in');
791	    el.style.opacity = '1';
792	    el.style.transform = 'none';
793	    Array.prototype.forEach.call(el.children, function(kid){
794	      kid.classList.add('sc-in');
795	      kid.style.opacity = '1';
796	      kid.style.transform = 'none';
797	      /* .pricelist .price is a grandchild (span inside the li), driven by its
798	         own CSS rule keyed off the li's sc-in class — force it directly too. */
799	      Array.prototype.forEach.call(kid.querySelectorAll('.price'), function(p){
800	        p.style.opacity = '1'; p.style.transform = 'none';
801	      });
802	    });
803	  }
804	  Array.prototype.forEach.call(document.querySelectorAll('[data-sc-in]'), function(el){
805	    var r = el.getBoundingClientRect();
806	    if (r.top < innerHeight && r.bottom > 0) revealNow(el);
807	  });
808	  setTimeout(function(){
809	    Array.prototype.forEach.call(document.querySelectorAll('[data-sc-in]'), revealNow);
810	  }, 3000);
811	
812	  addEventListener('scroll', onScroll, { passive:true });
813	  addEventListener('resize', function(){
814	    measureGeometry();
815	    if (forced !== null) apply(forced);
816	    else if (!skipScroll) onScroll();
817	  });
818	  init();
819	  if (document.fonts && document.fonts.load){
