1	<!doctype html>
2	<html lang="sv">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
6	<title>Alunix: Er hemsida är nutidens visitkort</title>
7	<meta name="description" content="Alunix är en webbyrå i Sverige. Webbdesign, design och system. Allt på ett ställe.">
8	<link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' fill='%231B1F1C'/></svg>">
9	<link rel="preconnect" href="https://fonts.googleapis.com">
10	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
11	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62.5..125,100..900&family=Familjen+Grotesk:wght@400;500;600&display=swap">
12	<script>document.documentElement.classList.add('js');</script>
13	<link rel="stylesheet" href="scrollcraft.css">
14	<style>
15	/*
16	  design · pre-emit critique: P5 H4 E4 S5 R5 V4
17	  K2 Affischen v2, runda 3 — hela sidan.
18	  Auktoritet: typen (ALU/NIX, sedan VI BYGGER ERT VARUMÄRKE). Viker: fotot (en
19	  dämpad plate i heron, skärmbilder som plates i akt B), färgen (ingen accent,
20	  fem toner totalt), siffrorna (kickers i akt C, aldrig ordmärkesgrad).
21	  Reference lock: Spring/Summer (primär — krossad affischtyp, femfärgstak,
22	  typsatt klocka i nav) + Indoek (lånad detalj — foto maskat genom bokstävernas
23	  öppningar, A-K2:s bevisade inkScan()-teknik). Inga hex eller typsnitt
24	  kopierade rakt av.
25	  Typsnitt: Archivo (display, en variabel familj) + Familjen Grotesk (register).
26	  Roller korsar aldrig. Ordmärket ALU/NIX vid normal bredd (100%); alla senare
27	  rubriker ("VI BYGGER ERT VARUMÄRKE.", "Alla har rätt till bra design.") vid
28	  smalare bredd (82%) — samma familjs breddaxel gör kontrasten, ingen tredje
29	  font.
30	  Runda 3-rättelse: andningen är en ISÄRGLIDNING, inte en korstoning. ALU och
31	  NIX förblir bläcksvarta hela tiden; raderna glider isär via transform (aldrig
32	  opacitet på bokstäverna) och rubriken reser sig i gapet som uppstår.
33	*/
34	:root{
35	  /* ---- fem färger, ingen accent ---- */
36	  --paper:  oklch(85% 0.028 135);
37	  --ink:    oklch(22% 0.012 150);
38	  --white:  oklch(98.5% 0.004 120);
39	  --line-1: oklch(74% 0.024 135);
40	  --line-2: oklch(45% 0.02 140);
41	  --line-2-onink: oklch(68% 0.02 140);
42	
43	  --font-display: "Archivo", "Helvetica Neue", Arial, sans-serif;
44	  --font-text:    "Familjen Grotesk", "Helvetica Neue", Arial, sans-serif;
45	
46	  --bar: 52px;
47	  --gutter: clamp(20px, 3.2vw, 48px);
48	  --maxw: 1680px;
49	  --ease: cubic-bezier(.16,1,.3,1);
50	  --step: cubic-bezier(.2,.8,.2,1);
51	
52	  /* engine tokens: reused, no new hue introduced anywhere */
53	  --sc-canvas: var(--paper);
54	  --sc-surface: var(--white);
55	  --sc-ink: var(--ink);
56	  --sc-ink-soft: var(--line-2);
57	  --sc-accent: var(--ink);
58	  --sc-accent-ink: var(--paper);
59	  --sc-font-display: var(--font-display);
60	  --sc-font-text: var(--font-text);
61	  color-scheme: light;
62	}
63	@media (max-width: 899px){
64	  :root{ --bar: 46px; }
65	}
66	
67	*,*::before,*::after{ box-sizing:border-box }
68	html{ background:var(--paper); overflow-x:clip }
69	body{ margin:0; overflow-x:clip; font-family:var(--font-text); font-weight:400;
70	      font-size:clamp(15px,0.92vw + 11px,18px); line-height:1.45; color:var(--ink);
71	      background:var(--sc-canvas); -webkit-font-smoothing:antialiased }
72	img,svg{ display:block; max-width:100% }
73	a{ color:inherit; text-decoration:none }
74	a:hover{ text-decoration:underline; text-underline-offset:.2em }
75	:focus-visible{ outline:2px solid var(--ink); outline-offset:3px; border-radius:2px }
76	/* Runda 6, fynd 1: :focus-visible mot avslutets driftade mörka grund mäter
77	   1,04:1 (var(--ink) på var(--ink)-nära bakgrund) — .paper mot samma grund
78	   mäter ≈9,7:1. Scopat till .close, aldrig globalt: resten av sidan har
79	   pappersvit botten hela tiden, där var(--ink) redan bär. */
80	.close :focus-visible{ outline-color:var(--paper); outline-offset:3px }
81	.sr-only{ position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap; border:0; padding:0; margin:-1px }
82	.wrap{ max-width:var(--maxw); margin:0 auto; padding-inline:var(--gutter) }
83	
84	.caps{ font-family:var(--font-text); font-size:11px; line-height:1.4; font-weight:600;
85	       letter-spacing:.16em; text-transform:uppercase; color:var(--line-2) }
86	
87	/* ---------------------------------------------------------------- toppbar */
88	.bar{ position:sticky; top:0; z-index:30; height:var(--bar);
89	      background:var(--paper); border-bottom:1px solid var(--line-1) }
90	/* Runda 6, fynd 13: klockan ska stå typsatt i mitten av toppbaren (Spring/
91	   Summer-referensen), inte hänga ihop med mejladressen som ett andra
92	   höger-element. Tre zoner i grid ger en RIKTIG mittpunkt oavsett hur breda
93	   logga/mejl råkar vara, till skillnad från en flex-rad där bara ett
94	   margin-right:auto skjuter allt annat åt höger som en klump. */
95	.bar .wrap{ height:100%; display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:var(--gutter) }
96	.bar .mark{ display:flex; align-items:center; gap:9px; justify-self:start; font-weight:600; font-size:14px }
97	.bar .mark svg{ width:14px; height:19px }
98	.bar .clock{ font-family:var(--font-text); font-variant-numeric:tabular-nums; display:flex; gap:.55em;
99	             justify-self:center; font-size:14px; font-weight:500 }
100	.bar .mail{ justify-self:end; font-size:14px; font-weight:500 }
101	@media (max-width:560px){ .bar .clock span{ display:none } .bar .mark span.name{ display:none } }
102	
103	/* --------------------------------------------------------- akt A: heron --- */
104	/* En flow-akts progress blir positiv en hel skärmhöjd innan akten faktiskt
105	   syns (top - vh), så akt E:s data-sc-drift börjar färga --sc-canvas medan
106	   läsaren fortfarande läser prislistan ovanför. Varje tidigare sektion får
107	   därför en egen ogenomskinlig botten så den aldrig visar den drivande
108	   sidbottnen förrän akt E:s egen ruta faktiskt är i vy. */
109	.hero{ position:relative; background:var(--paper) }
110	/* height set by the engine via data-sc-span while pinned; stripped to auto
111	   below (JS) before mount() ever runs when reduced motion is on, so there is
112	   no dead scroll track left behind (F-001). */
113	html:not(.js) .hero, .rm .hero{ height:auto }
114	.stage{ position:sticky; top:var(--bar); height:calc(100vh - var(--bar)); overflow:clip;
115	        display:flex; flex-direction:column; justify-content:space-between; padding-block:clamp(14px,2.4vh,26px) 0 }
116	.rm .stage, html:not(.js) .stage{ position:static; height:auto; overflow:visible; padding-block:clamp(28px,5vh,56px) }
117	/* Below 899px the composition stacks to one column (plate above block) and
118	   the poster rows alone already exceed a phone/tablet viewport height — the
119	   pinned stage forcing everything into 100vh made the wordmark bleed into the
120	   copy underneath it. Below that width the hero behaves like reduced motion:
121	   no pin, no scrub, the "opened" section carries the formed state instead. */
122	@media (max-width:899px){ .stage{ position:static; height:auto; overflow:visible; padding-block:clamp(28px,5vh,56px) } }
123	
124	/* Runda 5: .desc/.under tonar bort med --open i stället för att flytta sig —
125	   .under fyller redan sin tilldelade höjd exakt i vila (uppmätt: dess egen
126	   botten föll på stagets egen 900px-gräns), så att FLYTTA den (translateY)
127	   klippte bort radens andra textrad av misstag. Opacitet kostar ingen layout
128	   och kan aldrig klippas: när den är osynlig finns inget kvar att kollidera
129	   med, så raderna får fritt utrymme utan att röra vid något synligt.
130	   --open ärvs från #stage, satt av JS. */
131	.desc{ margin:0 0 clamp(4px,0.9vh,10px); max-width:38ch; font-size:clamp(15px,1.15vw,19px); color:var(--ink);
132	       /* emil-design-eng: fadea klart INNAN raden fysiskt når hit (open≈0,6),
133	          inte exakt vid open=1 — annars hinner den solida bokstaven (z-index:1)
134	          måla över en fortfarande-halvsynlig textrad, vilket läser som att
135	          bokstaven "suddar ut" texten i stället för en ren övergång. */
136	       opacity:calc(1 - min(1, var(--open,0) * 1.6)) }
137	
138	/* --- kompositionen: blocket + platen bredvid, platen aldrig under --- */
139	.composition{ display:grid; grid-template-columns:minmax(0,7fr) minmax(0,3fr); gap:var(--gutter);
140	              align-items:start; flex:1 1 auto; min-height:0; padding-block:6vh 1vh }
141	/* Runda 6, fynd 14: platen låg FÖRE ordmärket i mobilens stapel (order:-1) —
142	   fotot mötte besökaren innan blocket, tvärtemot desktopläsordningen (blocket
143	   är auktoriteten, se filens öppningskommentar). Tar bort ordet, DOM-ordningen
144	   (blocket, sedan platen) räcker. */
145	@media (max-width:899px){
146	  .composition{ grid-template-columns:minmax(0,1fr); gap:18px }
147	}
148	
149	.block{ position:relative; display:flex; flex-direction:column; min-width:0 }
150	.row{ position:relative; min-width:0; z-index:1 }
151	/* krossad bas: raderna rör nästan vid varandra i vila (--open:0). Separationen
152	   är ett transform ovanpå denna bas — det stör aldrig flödet, så blocket
153	   krockar aldrig med vad som ligger under det (runda 2:s 768px-bugg). */
154	.row-b{ margin-top:-2.6vw }
155	/* Runda 4: gapet mäts i vh (den faktiskt begränsande dimensionen i en pinnad
156	   100vh-hög scen), inte vw — annars skalar separationen med bredd, inte höjd,
157	   och rubriken tvingas till lässtorlek för att få plats. */
158	/* Runda 5: separationen minskad (5,5/8vh → 4/6vh) så gapet blir rubrikens
159	   höjd plus luft, inte mer — JS-konstanterna ROW_A_VH/ROW_B_VH måste matcha
160	   dessa två tal exakt, se signaturaktens script. */
161	.row-a{ transform: translateY(calc(var(--open,0) * -14vh)) }
162	.row-b{ transform: translateY(calc(var(--open,0) * 11vh)) }
163	@media (max-width:899px){ .row-b{ margin-top:0.4em } }
164	
165	.fa{ display:block }
166	.fa svg{ display:block; width:100%; height:auto; overflow:visible }
167	.fa svg text{ font-family:var(--font-display); font-weight:900; font-stretch:100%;
168	              font-size:100px; letter-spacing:-1.5px; fill:var(--ink) }
169	/* Ordmärket förblir bläcksvart hela tiden — ingen opacitet här, någonsin.
170	   Det är affischen, inte ett lager som ska tona bort. */
171	
172	/* rubriken som reser sig i gapet mellan raderna. Zero-height ankare mellan
173	   row-a och row-b i flödet, sedan centrerad via translateY(-50%) — så att
174	   den alltid sitter exakt i sömmen oavsett hur mycket raderna separerat. */
175	.headingWrap{ position:relative; height:0; overflow:visible; z-index:2 }
176	.headingWrap h2{ position:absolute; left:0; right:0; top:0; transform:translateY(-50%); margin:0;
177	                 font-family:var(--font-display); font-weight:900; font-stretch:82%; text-transform:uppercase;
178	                 letter-spacing:-0.02em; line-height:1; color:var(--ink);
179	                 /* satt av JS: mätt ur det faktiska gapet vid p=1, se measureGeometry().
180	                    clamp() är bara en no-js/pre-mätning-reserv. */
181	                 font-size:var(--heading-fs, clamp(1.5rem, 5.4vh, 3.6rem)) }
182	.headingWrap .hline{ display:block }
183	#block .headingWrap .hline{ opacity:0; transform:translateY(10px) }
184	/* Runda 6, fynd 9 (blockerande): :not(.rm) uteslöt reduced motion helt, så
185	   ?preview=open under prefers-reduced-motion visade ett tomt gap — JS satte
186	   --l1/--l2 korrekt till 1, men ingen regel läste dem under .rm, så
187	   basregelns opacity:0 (ovan) vann. Under vanlig reduced motion (ingen
188	   preview) är --l1/--l2 redan 0 via apply(0) i init(), så denna regel ändrar
189	   inget normalt beteende — den gör bara den forcerade förhandsvisningen
190	   möjlig att se. */
191	.js #block .headingWrap .hline:nth-child(1){ opacity:var(--l1,0); transform:translateY(calc((1 - var(--l1,0)) * 10px)) }
192	.js #block .headingWrap .hline:nth-child(2){ opacity:var(--l2,0); transform:translateY(calc((1 - var(--l2,0)) * 10px)) }
193	
194	.under{ margin-top:clamp(4px,0.8vh,10px); opacity:calc(1 - min(1, var(--open,0) * 1.6)) }
195	.site{ margin:0; font-family:var(--font-text); font-size:12px; font-weight:600; letter-spacing:.14em;
196	       text-transform:uppercase; color:var(--line-2) }
197	
198	.lead{ margin-top:clamp(14px,2.4vh,26px); max-width:46ch }
199	.lead h1{ margin:0 0 .4em; font-family:var(--font-text); font-weight:600; font-size:clamp(16px,1.3vw,20px); line-height:1.35 }
200	.lead p{ margin:0; color:var(--ink) }
201	
202	/* --- platen: en dämpad svartvit dokumentärbild, aldrig under ordmärket --- */
203	.plate{ position:relative; align-self:start }
204	.plate figure{ margin:0; border:1px solid var(--line-1); border-radius:2px; overflow:hidden; background:var(--white) }
205	.plate img{ width:100%; height:auto; aspect-ratio:4/5; object-fit:cover; filter:grayscale(1) contrast(1.04) brightness(1.01) }
206	.plate figcaption{ margin-top:8px; font-family:var(--font-text); font-size:11px; letter-spacing:.1em;
207	                    text-transform:uppercase; color:var(--line-2) }
208	@media (max-width:899px){
209	  .plate img{ aspect-ratio:16/9 }
