function onScroll(){
  if (forced !== null || skipScroll) return;
  var top = heroAct.offsetTop, h = heroAct.offsetHeight;
  var p;
  if (narrow){
    /* heroAct sits right at the top of the document (only the 46-52px bar
       above it) — the flow formula's "one viewport before" entry point
       (top - vh) is negative, i.e. does not exist as a real scroll
       position. Using it unclamped meant scrollY=0 (page load, before any
       scrolling at all) already mapped to raw≈0.48 — deep into the byte
       cycle, showing Hyperborea's site name instead of Calyx's on a fresh
       load. entryY clamps to what's actually reachable (0 when the section
       is this close to the top); exitY is unchanged (bottom of content
       reaching the top of the viewport, i.e. fully scrolled past). */
    var entryY = Math.max(top - innerHeight, 0);
    var exitY = top + h;
    p = clamp((scrollY - entryY) / Math.max(exitY - entryY, 1), 0, 1);
  } else {
    var travel = Math.max(h - innerHeight, 1);
    p = clamp((scrollY - top) / travel, 0, 1);
  }
  target = p;
  if (!raf){ raf = true; requestAnimationFrame(function(){ frame(); raf = false; }); }
}

